<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class PlaceController extends Controller {
 private function owner(){return auth('app_users')->user()?->id;}
 private function adult(){ $u=auth('app_users')->user();return $u && !$u->is_block && $u->dob && \Carbon\Carbon::parse($u->dob)->age>=18; }
 private function rules(){return ['title'=>'required|string|max:120','category'=>'required|in:date,stay,spa','description'=>'required|string|max:4000','country'=>'required|string|max:100','district'=>'required|string|max:100','town'=>'required|string|max:100','address'=>'required|string|max:250','latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180','currency_code'=>'required|exists:currencies,code','price_min'=>'required|integer|min:0|max:1000000000','price_max'=>'required|integer|gte:price_min|max:1000000000','price_unit'=>'required|in:person,night,session','includes'=>'required|string|max:3000','image_url'=>'nullable|url|starts_with:https://|max:500'];}
 private function unit($v){$expected=['date'=>'person','stay'=>'night','spa'=>'session'][$v['category']];if($v['price_unit']!==$expected)throw ValidationException::withMessages(['price_unit'=>'Use '.$expected.' pricing for this category.']);}
 private function enabledCurrency($code){if(!DB::table('currencies')->where('code',$code)->where('enabled',true)->exists())throw ValidationException::withMessages(['currency_code'=>'Choose an enabled currency.']);}
 public function index(Request $r){$v=$r->validate(['category'=>'nullable|in:date,stay,spa','currency'=>'required|exists:currencies,code','budget_min'=>'nullable|integer|min:0','budget_max'=>'nullable|integer|min:0|gte:budget_min','district'=>'nullable|string|max:100']);$q=DB::table('place_listings')->where('published',true)->where('status','approved')->where('currency_code',$v['currency']);$this->enabledCurrency($v['currency']);foreach(['category','district'] as $k)if(!empty($v[$k]))$q->where($k,$v[$k]);if(isset($v['budget_min']))$q->where('price_max','>=',$v['budget_min']);if(isset($v['budget_max']))$q->where('price_min','<=',$v['budget_max']);return response()->json(['status'=>true,'data'=>$q->select('id','title','category','description','country','district','town','address','latitude','longitude','currency_code','price_min','price_max','price_unit','includes','image_url')->orderBy('price_min')->limit(80)->get(),'message'=>'Price ranges are estimates. Select an available slot for an exact reservation quote.']);}
 public function slots($id){$p=DB::table('place_listings')->where('id',$id)->where('status','approved')->where('published',true)->first();if(!$p)return response()->json(['status'=>false],404);$slots=DB::table('place_slots')->where('listing_id',$id)->where('enabled',true)->where('starts_at','>',now())->orderBy('starts_at')->limit(100)->get();foreach($slots as $s){$used=DB::table('place_reservation_slots as rs')->join('place_reservations as r','r.id','=','rs.reservation_id')->where('rs.slot_id',$s->id)->where(function($q){$q->where('r.status','confirmed')->orWhere(function($q){$q->where('r.status','requested')->where('r.created_at','>',now()->subDay());});})->sum('rs.quantity');$s->remaining=max(0,$s->capacity-$used);$s->starts_at=\Carbon\Carbon::parse($s->starts_at,'UTC')->toIso8601String();$s->ends_at=\Carbon\Carbon::parse($s->ends_at,'UTC')->toIso8601String();}return response()->json(['status'=>true,'data'=>$slots,'listing'=>array_intersect_key((array)$p,array_flip(['id','title','category','description','country','district','town','address','latitude','longitude','currency_code','price_min','price_max','price_unit','includes','image_url']))]);}
 public function submit(Request $r){if(!$this->adult())return response()->json(['status'=>false,'message'=>'Complete an adult profile first.'],403);$v=$r->validate($this->rules());$this->unit($v);$this->enabledCurrency($v['currency_code']);$v['owner_id']=$this->owner();$v['status']='pending';$v['published']=false;$v['created_at']=$v['updated_at']=now();$id=DB::table('place_listings')->insertGetId($v);return response()->json(['status'=>true,'data'=>['id'=>$id,'status'=>'pending'],'message'=>'Listing submitted for administrator review.']);}
 public function ownerReservations(){
  $rows=DB::table('place_reservations as r')->join('place_listings as p','p.id','=','r.listing_id')->where('p.owner_id',$this->owner())->select('r.id','r.reference','r.quantity','r.total_minor','r.currency_code','r.status','r.review_note','r.created_at','p.title')->orderByDesc('r.id')->limit(100)->get();
  foreach($rows as $row)if($row->status==='requested'&&$row->created_at<=now()->subDay())$row->status='expired';
  return response()->json(['status'=>true,'data'=>$rows,'message'=>'Admin confirms requests after checking venue availability. No online payment collected.']);
 }
 public function mine(){return response()->json(['status'=>true,'data'=>DB::table('place_listings')->where('owner_id',$this->owner())->orderByDesc('id')->limit(100)->get()]);}
 public function reservations(){ $rows=DB::table('place_reservations as r')->join('place_listings as p','p.id','=','r.listing_id')->where('r.user_id',$this->owner())->select('r.*','p.title','p.category','p.address','p.town')->orderByDesc('r.id')->limit(100)->get();foreach($rows as $row){$times=DB::table('place_reservation_slots as rs')->join('place_slots as s','s.id','=','rs.slot_id')->where('rs.reservation_id',$row->id)->selectRaw('MIN(s.starts_at) as starts_at, MAX(s.ends_at) as ends_at')->first();$row->starts_at=$times?->starts_at?\Carbon\Carbon::parse($times->starts_at,'UTC')->toIso8601String():null;$row->ends_at=$times?->ends_at?\Carbon\Carbon::parse($times->ends_at,'UTC')->toIso8601String():null;if($row->status==='requested'&&$row->created_at<=now()->subDay())$row->status='expired';}return response()->json(['status'=>true,'data'=>$rows]); }
 public function reserve(Request $r){if(!$this->adult())return response()->json(['status'=>false,'message'=>'Complete an adult profile first.'],403);$v=$r->validate(['listing_id'=>'required|integer','slot_ids'=>'required|array|min:1|max:7','slot_ids.*'=>'required|integer|distinct','quantity'=>'required|integer|min:1|max:20','request_key'=>'required|uuid']);$me=$this->owner();return DB::transaction(function()use($v,$me){$account=DB::table('users')->where('id',$me)->lockForUpdate()->first();if(!$account || $account->is_block)return response()->json(['status'=>false],403);$p=DB::table('place_listings')->where('id',$v['listing_id'])->lockForUpdate()->first();if(!$p||!$p->published||$p->status!=='approved')return response()->json(['status'=>false,'message'=>'Listing unavailable.'],409);$old=DB::table('place_reservations')->where('user_id',$me)->where('request_key',$v['request_key'])->first();if($old){$ids=DB::table('place_reservation_slots')->where('reservation_id',$old->id)->pluck('slot_id')->sort()->values()->all();$new=$v['slot_ids'];sort($new);if($old->listing_id!=$p->id||$old->quantity!=$v['quantity']||$ids!=$new)return response()->json(['status'=>false,'message'=>'Request key already used for another reservation.'],409);return response()->json(['status'=>true,'data'=>$old]);}
 $this->enabledCurrency($p->currency_code);$slots=DB::table('place_slots')->where('listing_id',$p->id)->whereIn('id',$v['slot_ids'])->orderBy('starts_at')->lockForUpdate()->get();if($slots->count()!=count($v['slot_ids'])||($p->category!=='stay'&&$slots->count()!=1))return response()->json(['status'=>false,'message'=>'Choose valid availability.'],422);
 $total=0;$last=null;foreach($slots as $s){if(!$s->enabled||$s->starts_at<=now())return response()->json(['status'=>false,'message'=>'This slot is unavailable.'],409);if($p->category==='stay'&&(\Carbon\Carbon::parse($s->ends_at)->diffInSeconds(\Carbon\Carbon::parse($s->starts_at),true)!=86400||($last!==null&&$last!=$s->starts_at)))return response()->json(['status'=>false,'message'=>'Choose consecutive nights, up to one week.'],422);$last=$s->ends_at;$used=DB::table('place_reservation_slots as rs')->join('place_reservations as r','r.id','=','rs.reservation_id')->where('rs.slot_id',$s->id)->where(function($q){$q->where('r.status','confirmed')->orWhere(function($q){$q->where('r.status','requested')->where('r.created_at','>',now()->subDay());});})->sum('rs.quantity');if($used+$v['quantity']>$s->capacity)return response()->json(['status'=>false,'message'=>'Not enough availability.'],409);$total+=$s->amount_minor*$v['quantity'];}
 $id=DB::table('place_reservations')->insertGetId(['reference'=>(string)Str::uuid(),'user_id'=>$me,'listing_id'=>$p->id,'request_key'=>$v['request_key'],'quantity'=>$v['quantity'],'total_minor'=>$total,'currency_code'=>$p->currency_code,'status'=>'requested','created_at'=>now(),'updated_at'=>now()]);foreach($slots as $s)DB::table('place_reservation_slots')->insert(['reservation_id'=>$id,'slot_id'=>$s->id,'quantity'=>$v['quantity']]);if($p->owner_id && $p->owner_id!=$me)\App\Services\UserAlerts::send($p->owner_id,'KETUA bookings','New reservation request for '.$p->title.'. Open your listing bookings to review.');return response()->json(['status'=>true,'data'=>DB::table('place_reservations')->find($id),'message'=>'Request sent. No payment taken. The venue must confirm your reservation.']);});}
 public function cancel(Request $r){$v=$r->validate(['id'=>'required|integer']);return DB::transaction(function()use($v){$res=DB::table('place_reservations')->where('id',$v['id'])->where('user_id',$this->owner())->first();if(!$res)return response()->json(['status'=>false],404);DB::table('place_listings')->where('id',$res->listing_id)->lockForUpdate()->first();DB::table('place_reservations')->where('id',$res->id)->whereIn('status',['requested','confirmed'])->update(['status'=>'cancelled','updated_at'=>now()]);return response()->json(['status'=>true]);});}
 public function admin(){return view('places',['places'=>DB::table('place_listings')->orderByDesc('id')->limit(100)->get(),'reservations'=>DB::table('place_reservations as r')->join('place_listings as p','p.id','=','r.listing_id')->select('r.*','p.title')->orderByDesc('r.id')->limit(100)->get(),'currencies'=>DB::table('currencies')->where('enabled',true)->get(),'slots'=>DB::table('place_slots')->orderByDesc('id')->limit(200)->get()]);}
 public function save(Request $r){$v=$r->validate($this->rules()+['id'=>'nullable|integer|exists:place_listings,id','status'=>'required|in:pending,approved,rejected','published'=>'required|boolean','review_note'=>'nullable|string|max:2000']);$this->unit($v);$this->enabledCurrency($v['currency_code']);DB::transaction(function()use($v){$id=$v['id']??null;unset($v['id']);$v['published']=$v['status']==='approved'&&$v['published'];$v['updated_at']=now();if($id){$old=DB::table('place_listings')->where('id',$id)->lockForUpdate()->first();if($old->currency_code!==$v['currency_code']&&DB::table('place_reservations')->where('listing_id',$id)->exists())throw ValidationException::withMessages(['currency_code'=>'Keep the currency for existing reservations.']);DB::table('place_listings')->where('id',$id)->update($v);}else{$v['created_at']=now();DB::table('place_listings')->insert($v);}});return back()->with('success','Listing saved.');}
 public function slotSave(Request $r){$v=$r->validate(['listing_id'=>'required|integer|exists:place_listings,id','starts_at'=>'required|date|after:now','ends_at'=>'required|date|after:starts_at','amount_minor'=>'required|integer|min:0|max:1000000000','capacity'=>'required|integer|min:1|max:1000']);DB::transaction(function()use($v){$p=DB::table('place_listings')->where('id',$v['listing_id'])->lockForUpdate()->first();if($v['amount_minor']<$p->price_min||$v['amount_minor']>$p->price_max)throw ValidationException::withMessages(['amount_minor'=>'Keep the slot price within the listing price range.']);$start=\Carbon\Carbon::parse($v['starts_at'])->utc();$end=\Carbon\Carbon::parse($v['ends_at'])->utc();if($p->category==='stay'&&$start->diffInSeconds($end,true)!=86400)throw ValidationException::withMessages(['ends_at'=>'An AirStay slot must be exactly one night (24 hours).']);if(DB::table('place_slots')->where('listing_id',$p->id)->where('starts_at','<',$end)->where('ends_at','>',$start)->exists())throw ValidationException::withMessages(['starts_at'=>'Availability overlaps an existing slot.']);$v['starts_at']=$start;$v['ends_at']=$end;$v['created_at']=$v['updated_at']=now();DB::table('place_slots')->insert($v);});return back()->with('success','Availability added.');}
 public function review(Request $r){$v=$r->validate(['id'=>'required|integer|exists:place_reservations,id','status'=>'required|in:confirmed,rejected,cancelled','review_note'=>'nullable|string|max:2000']);DB::transaction(function()use($v){$res=DB::table('place_reservations')->find($v['id']);$p=DB::table('place_listings')->where('id',$res->listing_id)->lockForUpdate()->first();$res=DB::table('place_reservations')->find($v['id']);if(!in_array($res->status,['requested','confirmed']))throw ValidationException::withMessages(['status'=>'This request is closed.']);if($v['status']==='confirmed'&&$res->status==='requested'&&$res->created_at<=now()->subDay())throw ValidationException::withMessages(['status'=>'This hold has expired. Request new availability.']);if($v['status']==='confirmed'&&(!$p->published||$p->status!=='approved'))throw ValidationException::withMessages(['status'=>'Approve and publish the listing first.']);unset($v['id']);$v['updated_at']=now();DB::table('place_reservations')->where('id',$res->id)->update($v);\App\Services\UserAlerts::send($res->user_id,'KETUA reservation','Your reservation at '.$p->title.' is '.$v['status'].'. '.($v['review_note']??''));});return back()->with('success','Reservation updated.');}
}
